export interface SectionRow {
  heading: string;
  items: CatalogItem[];
}

export function buildSectionRows(
  sections: Readonly<Record<string, readonly CatalogItem[]>> | null,
  busy: boolean,
): SectionRow[] {
  if (busy) {
    return [{ heading: "Loading", items: [] }];
  }
  if (sections === null) {
    return [];
  }

  return Object.keys(sections)
    .sort((left, right) => left < right ? -1 : left > right ? 1 : 0)
    .map((heading) => ({
      heading,
      items: [...sections[heading]],
    }));
}

