import { buildSectionRows } from "./solution";
import type { CatalogItem } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

const loadingFromNull = buildSectionRows(null, true);
assert(JSON.stringify(loadingFromNull) === JSON.stringify([{ heading: "Loading", items: [] }]), "busy null input should return the loading row");

const sections: Readonly<Record<string, readonly CatalogItem[]>> = {
  beta: [{ sku: "b1", label: "Beta one" }, { sku: "b2", label: "Beta two" }],
  Alpha: [{ sku: "a1", label: "Alpha one" }],
  "": [],
};
const before = JSON.stringify(sections);
const loading = buildSectionRows(sections, true);
assert(JSON.stringify(loading) === JSON.stringify([{ heading: "Loading", items: [] }]), "busy input should ignore sections");

assert(buildSectionRows(null, false).length === 0, "non-busy null input should return an empty array");
const rows = buildSectionRows(sections, false);
assert(rows.map((row) => row.heading).join("|") === "|Alpha|beta", "rows should use own keys in ordinary ascending string order");
assert(rows[2].items.map((item) => item.sku).join(",") === "b1,b2", "item order should be preserved");
assert(rows[0].items.length === 0, "empty headings and item arrays should be retained");
assert(JSON.stringify(sections) === before, "building rows must not mutate input");
assert(rows[1].items[0] !== sections.Alpha[0] && rows[2].items[0] !== sections.beta[0], "item objects must be deeply copied");
rows[2].heading = "changed";
rows[2].items[0].label = "changed";
rows[2].items.push({ sku: "new", label: "new" });
assert(JSON.stringify(sections) === before, "mutating projected rows must not affect input");

const again = buildSectionRows(sections, false);
assert(again !== rows && again[1] !== rows[1] && again[1].items !== rows[1].items, "each projection should allocate new rows and item arrays");

